def stack_machine(instructions):
    stack = []
    for instr in instructions:
        if isinstance(instr, tuple):
            op = instr[0]
            if op == 'push':
                if len(instr) != 2:
                    raise ValueError(f"Invalid push instruction: {instr}")
                val = instr[1]
                stack.append(val)
            elif op == 'add':
                if len(instr) != 1:
                    raise ValueError(f"Invalid add instruction: {instr}")
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif op == 'multiply':
                if len(instr) != 1:
                    raise ValueError(f"Invalid multiply instruction: {instr}")
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif op == 'negate':
                if len(instr) != 1:
                    raise ValueError(f"Invalid negate instruction: {instr}")
                a = stack.pop()
                stack.append(-a)
            else:
                raise NotImplementedError(f"Unsupported operation: {op}")
        else:
            raise ValueError("Invalid instruction")
    if len(stack) != 1:
        raise ValueError("Stack must contain exactly one value")
    return stack[0]
